import {BUSINESSES,businessType,buildingLimit,researchChoices} from './businesses.js';import {CARDS} from './content.js';import {buildingImage} from './illustrations.js';
const fmt=n=>Math.round(n).toLocaleString('zh-CN');
export function businessPanel(g,id){const t=g.tiles[id],o=g.s.ownership[id],color=g.char().estateColor;if(!o||o.player!==g.player.id)return '<p>请先拥有这块地产。</p>';
 if(!o.level)return `<p class="panel-note">空地已归你所有。选择这次要建设的设施；常规建设每次停靠限一次。类型建成后固定，拆除后可重新选择。</p><div class="business-choices">${Object.entries(BUSINESSES).map(([key,b])=>`<article class="business-choice">${buildingImage({...t,buildingType:key},1,color)}<h3>${b.name}</h3><span class="badge">${b.max===1?'一级设施':'可加盖至五级'}</span><p>${b.text}</p><div class="row-head"><strong>${fmt(g.buildPrice(t,key))} 奶币</strong><button class="primary" data-act="construct" data-id="${id}" data-type="${key}" ${g.canConstruct(id,key)?'':'disabled'}>建设</button></div></article>`).join('')}</div>`;
 const type=businessType(o),b=BUSINESSES[type],max=buildingLimit(o);return `${buildingImage({...t,buildingType:o.buildingType},o.level,color)}<h3>${b.name} · ${o.level}/${max}级</h3><p>${b.text}</p><div class="stat-grid"><div class="stat-box"><strong>${g.rent(id)}</strong><span>参考收费</span></div><div class="stat-box"><strong>${o.level<max?g.buildPrice(t):'已达上限'}</strong><span>下一级建设费</span></div></div>${type==='research'?`<h3>研发进度 ${o.researchProgress||0}/3</h3><p>当前项目：${CARDS[o.researchCard||'dice'].name}。更换项目将重置进度。</p><div class="research-options">${researchChoices(o.level).map(key=>`<button class="secondary" data-act="research" data-id="${id}" data-key="${key}" ${o.researchCard===key?'disabled':''}>${CARDS[key].name}</button>`).join('')}</div>`:''}<p class="stock-explain">旅馆按入住天数、商场按抽签倍率、加油站按实际行程收费，预览仅作参考。住宅按街区联营；连锁店按全图分店数收费。</p><div class="button-grid"><button class="secondary" data-act="cancel">继续旅行</button><button class="primary" data-act="upgrade" data-id="${id}" ${g.canUpgrade(id)?'':'disabled'}>${o.level<max?'加盖一层':'不能继续加盖'}</button></div>`;
}
